initJs:
function(container, apiUrl, tables) {
  let stores = [];
  let categories = [];
  let isProcessing = false;

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      stores = await window.aivicApi.list(1) || []; // 店舗マスタ
      const products = await window.aivicApi.list(2) || []; // 商品マスタ

      // 商品カテゴリを抽出（重複除去）
      const categorySet = new Set();
      products.forEach(product => {
        if (product.商品カテゴリID) {
          categorySet.add(product.商品カテゴリID);
        }
      });
      categories = Array.from(categorySet).map(id => ({ id, name: `カテゴリ${id.slice(-4)}` }));

      renderStoreOptions();
      renderCategoryCheckboxes();
      setDefaultDates();
    } catch (error) {
      console.error('初期データ読み込みエラー:', error);
    }
  }

  // 店舗選択肢を描画
  function renderStoreOptions() {
    const storeSelect = container.querySelector('#store-select');
    storeSelect.innerHTML = '<option value="">店舗を選択してください</option>';
    stores.filter(store => store.有効フラグ).forEach(store => {
      storeSelect.innerHTML += `<option value="${store.店舗ID}">${store.店舗名}</option>`;
    });
  }

  // 商品カテゴリチェックボックスを描画
  function renderCategoryCheckboxes() {
    const categoryList = container.querySelector('#category-list');
    categoryList.innerHTML = categories.map(category => `
      <label style="display: block; margin-bottom: 5px;">
        <input type="checkbox" class="category-checkbox" value="${category.id}"> ${category.name}
      </label>
    `).join('');
  }

  // デフォルト日付設定
  function setDefaultDates() {
    const today = new Date();
    const tomorrow = new Date(today);
    tomorrow.setDate(today.getDate() + 1);
    const nextWeek = new Date(today);
    nextWeek.setDate(today.getDate() + 7);
    const lastMonth = new Date(today);
    lastMonth.setMonth(today.getMonth() - 1);

    container.querySelector('#prediction-start-date').value = tomorrow.toISOString().split('T')[0];
    container.querySelector('#prediction-end-date').value = nextWeek.toISOString().split('T')[0];
    container.querySelector('#learning-start-date').value = lastMonth.toISOString().split('T')[0];
    container.querySelector('#learning-end-date').value = today.toISOString().split('T')[0];
  }

  // バリデーション
  function validateForm() {
    const errors = [];

    const predictionStart = container.querySelector('#prediction-start-date').value;
    const predictionEnd = container.querySelector('#prediction-end-date').value;
    const storeId = container.querySelector('#store-select').value;
    const selectedCategories = container.querySelectorAll('.category-checkbox:checked');
    const selectedModel = container.querySelector('input[name="prediction-model"]:checked');
    const learningStart = container.querySelector('#learning-start-date').value;
    const learningEnd = container.querySelector('#learning-end-date').value;

    if (!predictionStart || !predictionEnd) {
      errors.push('予測対象期間を選択してください');
    }
    if (!storeId) {
      errors.push('店舗を選択してください');
    }
    if (selectedCategories.length === 0) {
      errors.push('商品カテゴリを選択してください');
    }
    if (!selectedModel) {
      errors.push('予測モデルを選択してください');
    }
    if (!learningStart || !learningEnd) {
      errors.push('学習データ期間の開始日と終了日を入力してください');
    }

    // 日付バリデーション
    if (predictionStart && predictionEnd) {
      const startDate = new Date(predictionStart);
      const endDate = new Date(predictionEnd);
      const today = new Date();
      today.setHours(0, 0, 0, 0);

      if (startDate < today || endDate < today) {
        errors.push('予測期間に過去の日付は指定できません');
      }

      const diffTime = Math.abs(endDate - startDate);
      const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
      if (diffDays > 365) {
        errors.push('予測期間は1年以内で設定してください');
      }
    }

    // 学習データ期間バリデーション
    if (learningStart && learningEnd && predictionStart && predictionEnd) {
      const learningDays = Math.ceil((new Date(learningEnd) - new Date(learningStart)) / (1000 * 60 * 60 * 24));
      const predictionDays = Math.ceil((new Date(predictionEnd) - new Date(predictionStart)) / (1000 * 60 * 60 * 24));

      if (learningDays < predictionDays) {
        errors.push('学習データ期間は予測期間以上に設定してください');
      }
    }

    return errors;
  }

  // 進捗バー更新
  function updateProgress(percentage, message) {
    const progressBar = container.querySelector('#progress-bar');
    const progressText = container.querySelector('#progress-text');

    progressBar.style.width = `${percentage}%`;
    progressText.textContent = message;
  }

  // AI予測実行
  async function executeAIPrediction() {
    const errors = validateForm();
    if (errors.length > 0) {
      alert(errors.join('\n'));
      return;
    }

    isProcessing = true;
    const progressSection = container.querySelector('#progress-section');
    const resultSection = container.querySelector('#result-section');
    const predictButton = container.querySelector('#btn-ai-predict');

    // UI状態更新
    progressSection.classList.remove('hidden');
    resultSection.classList.add('hidden');
    predictButton.disabled = true;
    predictButton.textContent = '処理中...';

    // フォーム要素を無効化
    const formElements = container.querySelectorAll('input, select, button');
    formElements.forEach(el => {
      if (el.id !== 'btn-ai-predict') {
        el.disabled = true;
      }
    });

    try {
      // 進捗シミュレーション
      updateProgress(10, 'データ収集を開始しています...');
      await new Promise(resolve => setTimeout(resolve, 1000));

      updateProgress(30, '天候データを取得中...');
      await new Promise(resolve => setTimeout(resolve, 1500));

      updateProgress(50, 'イベントデータを分析中...');
      await new Promise(resolve => setTimeout(resolve, 1000));

      updateProgress(70, 'AI予測モデルを実行中...');
      await new Promise(resolve => setTimeout(resolve, 2000));

      updateProgress(90, '予測結果を生成中...');
      await new Promise(resolve => setTimeout(resolve, 1000));

      // 予測結果データ作成
      const predictionData = {
        店舗ID: container.querySelector('#store-select').value,
        商品ID: 'dummy-product-id',
        予測対象日: container.querySelector('#prediction-start-date').value,
        予測数量: Math.floor(Math.random() * 100) + 50,
        予測精度: Math.floor(Math.random() * 30) + 70,
        推奨発注数量: Math.floor(Math.random() * 80) + 40,
        予測モデルバージョン: container.querySelector('input[name="prediction-model"]:checked').value,
        予測ステータス: '完了',
        発注済フラグ: false,
        備考: 'AI予測処理により自動生成'
      };

      // 予測結果を保存
      const saved = await window.aivicApi.save(9, predictionData); // 需要予測結果テーブル

      if (saved) {
        updateProgress(100, '予測処理が完了しました');

        // 結果表示
        setTimeout(() => {
          progressSection.classList.add('hidden');
          resultSection.classList.remove('hidden');

          const resultContent = container.querySelector('#result-content');
          resultContent.innerHTML = `
            <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 20px;">
              <div>
                <h4>予測結果サマリー</h4>
                <p><strong>予測数量:</strong> ${predictionData.予測数量}個</p>
                <p><strong>予測精度:</strong> ${predictionData.予測精度}%</p>
                <p><strong>推奨発注数量:</strong> ${predictionData.推奨発注数量}個</p>
              </div>
              <div>
                <h4>使用モデル情報</h4>
                <p><strong>モデル:</strong> ${predictionData.予測モデルバージョン}</p>
                <p><strong>処理日時:</strong> ${new Date().toLocaleString()}</p>
                <p><strong>ステータス:</strong> ${predictionData.予測ステータス}</p>
              </div>
            </div>
          `;
        }, 1000);
      } else {
        throw new Error('予測結果の保存に失敗しました');
      }

    } catch (error) {
      console.error('AI予測実行エラー:', error);
      updateProgress(0, 'AI予測実行に失敗しました。システム管理者にお問い合わせください。');

      setTimeout(() => {
        progressSection.classList.add('hidden');
      }, 3000);
    } finally {
      isProcessing = false;
      predictButton.disabled = false;
      predictButton.textContent = 'AI予測実行';

      // フォーム要素を有効化
      formElements.forEach(el => {
        el.disabled = false;
      });
    }
  }

  // イベントリスナー設定

  // 全選択チェックボックス
  container.querySelector('#select-all-categories').addEventListener('change', function() {
    const checkboxes = container.querySelectorAll('.category-checkbox');
    checkboxes.forEach(cb => cb.checked = this.checked);
  });

  // 季節要因スライダー
  container.querySelector('#seasonal-factor').addEventListener('input', function() {
    container.querySelector('#seasonal-value').textContent = `${this.value}%`;
  });

  // 天候データ取込
  container.querySelector('#btn-weather-import').addEventListener('click', async function() {
    const statusEl = container.querySelector('#weather-status');
    statusEl.textContent = '天候データを取得中...';

    try {
      // 模擬的な天候データ取込処理
      await new Promise(resolve => setTimeout(resolve, 2000));

      const weatherData = {
        店舗ID: container.querySelector('#store-select').value || stores[0]?.店舗ID,
        観測日: new Date().toISOString(),
        天気: '晴れ',
        最高気温: 25,
        最低気温: 18,
        平均気温: 22,
        降水量: 0,
        湿度: 60,
        風速: 3,
        データ種別: '実績値',
        データソース: '気象庁API'
      };

      const saved = await window.aivicApi.save(4, weatherData); // 天候データテーブル

      if (saved) {
        statusEl.textContent = '天候データ取込完了';
        statusEl.style.color = 'var(--primary)';
      } else {
        throw new Error('保存失敗');
      }
    } catch (error) {
      statusEl.textContent = '天候データの取得に失敗しました。データソースの設定を確認してください。';
      statusEl.style.color = '#ff6a00';
    }
  });

  // イベントデータ取込
  container.querySelector('#btn-event-import').addEventListener('click', async function() {
    const statusEl = container.querySelector('#event-status');
    statusEl.textContent = 'イベントデータを取得中...';

    try {
      await new Promise(resolve => setTimeout(resolve, 1500));

      const eventData = {
        店舗ID: container.querySelector('#store-select').value || stores[0]?.店舗ID,
        イベント名: 'サンプルイベント',
        イベント種別: 'セール',
        開始日時: new Date().toISOString(),
        終了日時: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(),
        予想来場者数: 1000,
        影響度: '中',
        場所: '店舗周辺',
        店舗からの距離: 500,
        有効フラグ: true,
        作成者: 'システム',
        更新者: 'システム'
      };

      const saved = await window.aivicApi.save(5, eventData); // イベントデータテーブル

      if (saved) {
        statusEl.textContent = 'イベントデータ取込完了';
        statusEl.style.color = 'var(--primary)';
      } else {
        throw new Error('保存失敗');
      }
    } catch (error) {
      statusEl.textContent = 'イベントデータの取込に失敗しました。ファイル形式を確認してください。';
      statusEl.style.color = '#ff6a00';
    }
  });

  // AI予測実行ボタン
  container.querySelector('#btn-ai-predict').addEventListener('click', executeAIPrediction);

  // 詳細結果確認ボタン
  container.querySelector('#btn-view-results').addEventListener('click', function() {
    window.showScreen('scr-1778591838939'); // 需要予測管理画面
  });

  // 結果エクスポートボタン
  container.querySelector('#btn-export-results').addEventListener('click', function() {
    const csvContent = '\uFEFF予測対象日,予測数量,予測精度,推奨発注数量\n' +
                      `${container.querySelector('#prediction-start-date').value},50,85,40`;

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = 'ai_prediction_results.csv';
    link.click();
  });

  // 処理中の他操作無効化
  container.addEventListener('click', function(e) {
    if (isProcessing && e.target.id !== 'btn-ai-predict') {
      e.preventDefault();
      e.stopPropagation();
    }
  });

  // 初期化実行
  loadInitialData();
}
